import { Hono } from '../clone/src/hono'
import { validator } from '../clone/src/validator'
const mk = () => {
  const app = new Hono()
  app.post('/v', validator('form', (v) => v), async (c) => {
    try { return c.json({ ok: await c.req.parseBody() }) } catch (e) { return c.json({ err: String(e) }) }
  })
  app.post('/f', async (c) => {
    await c.req.formData()
    try { return c.json({ ok: await c.req.parseBody() }) } catch (e) { return c.json({ err: String(e) }) }
  })
  app.post('/p', async (c) => {
    const a = await c.req.parseBody()
    const t = await c.req.text()
    return c.json({ a, t })
  })
  return app
}
const app = mk()
